# ── DIAGNOSTIC: Test parse_kv_line on first 5 data lines ──
print("\n🔍 DIAGNOSTIC — First 5 parsed lines:")
sample_lines = [
    l for l in raw_text.split('\n')
    if l.strip() and not l.strip().startswith('#')
][:5]

for i, line in enumerate(sample_lines):
    parsed = parse_kv_line(line, set(COLUMN_MAP.keys()) | {"EQID"})
    print(f"\nLine {i+1} raw  : {repr(line[:120])}")
    print(f"Line {i+1} parsed ({len(parsed)} fields): {parsed}")
